   47: void QuestHandlers::HandleQuestgiverStatusQuery(WorldSession& session, WorldPacket& recv_data)
   48: {
   49:     ObjectGuid guid;
   50:     recv_data >> guid;
   51:     uint32 dialogStatus = DIALOG_STATUS_NONE;
   52: 
   53:     Object* questgiver = session.GetPlayer()->GetObjectByTypeMask(guid, TYPEMASK_CREATURE_OR_GAMEOBJECT);
   54: 
   55:     if (!questgiver)
   56:     {
   57:         DETAIL_LOG("Error in CMSG_QUESTGIVER_STATUS_QUERY, called for not found questgiver %s", guid.GetString().c_str());
   58:         return;
   59:     }
   60: 
   61:     DEBUG_LOG("WORLD: Received opcode CMSG_QUESTGIVER_STATUS_QUERY - for %s to %s", session.GetPlayer()->GetGuidStr().c_str(), guid.GetString().c_str());
   62: 
   63:     switch (questgiver->GetTypeId())
   64:     {
   65:         case TYPEID_UNIT:
   66:         {
   67:             Creature* cr_questgiver = (Creature*)questgiver;
   68: 
   69:             if (!cr_questgiver->IsHostileTo(session.GetPlayer()))       // not show quest status to enemies
   70:             {
   71:                 dialogStatus = sScriptHooks.GetDialogStatus(session.GetPlayer(), cr_questgiver);
   72: 
   73:                 if (dialogStatus > DIALOG_STATUS_REWARD_REP)
   74:                 {
   75:                     dialogStatus = session.getDialogStatus(session.GetPlayer(), cr_questgiver, DIALOG_STATUS_NONE);
   76:                 }
   77:             }
   78:             break;
   79:         }
   80:         case TYPEID_GAMEOBJECT:
   81:         {
   82:             GameObject* go_questgiver = (GameObject*)questgiver;
   83:             dialogStatus = sScriptHooks.GetDialogStatus(session.GetPlayer(), go_questgiver);
   84: 
   85:             if (dialogStatus > DIALOG_STATUS_REWARD_REP)
   86:             {
   87:                 dialogStatus = session.getDialogStatus(session.GetPlayer(), go_questgiver, DIALOG_STATUS_NONE);
   88:             }
   89: 
   90:             break;
   91:         }
   92:         default:
   93:             sLog.outError("QuestGiver called for unexpected type %u", questgiver->GetTypeId());
   94:             break;
   95:     }
   96: 
   97:     // inform client about status of quest
   98:     session.GetPlayer()->PlayerTalkClass->SendQuestGiverStatus(dialogStatus, guid);
   99: }
