  101: /**
  102:  * @brief Handles the initial hello interaction with a quest giver.
  103:  *
  104:  * @param recv_data The received opcode packet.
  105:  */
  106: void QuestHandlers::HandleQuestgiverHello(WorldSession& session, WorldPacket& recv_data)
  107: {
  108:     ObjectGuid guid;
  109:     recv_data >> guid;
  110: 
  111:     DEBUG_LOG("WORLD: Received opcode CMSG_QUESTGIVER_HELLO - for %s to %s", session.GetPlayer()->GetGuidStr().c_str(), guid.GetString().c_str());
  112: 
  113:     Creature* pCreature = session.GetPlayer()->GetNPCIfCanInteractWith(guid, UNIT_NPC_FLAG_NONE);
  114:     if (!pCreature)
  115:     {
  116:         DEBUG_LOG("WORLD: HandleQuestgiverHelloOpcode - for %s to %s not found or you can't interact with him.", session.GetPlayer()->GetGuidStr().c_str(), guid.GetString().c_str());
  117:         return;
  118:     }
  119: 
  120:     // remove fake death
  121:     if (session.GetPlayer()->IsFeigningDeath())
  122:     {
  123:         session.GetPlayer()->RemoveSpellsCausingAura(SPELL_AURA_FEIGN_DEATH);
  124:     }
  125: 
  126:     // Stop the npc if moving; a patrol holds its leg for a while so the player can talk
  127:     pCreature->HoldForPlayer();
  128: 
  129:     if (sScriptHooks.OnGossipHello(session.GetPlayer(), pCreature))
  130:     {
  131:         return;
  132:     }
  133: 
  134:     session.GetPlayer()->PrepareGossipMenu(pCreature, pCreature->GetCreatureInfo()->GossipMenuId);
  135:     session.GetPlayer()->SendPreparedGossip(pCreature);
  136: }
