  138: /**
  139:  * @brief Handles accepting a quest from a quest giver or shared source.
  140:  *
  141:  * @param recv_data The received opcode packet.
  142:  */
  143: void QuestHandlers::HandleQuestgiverAcceptQuest(WorldSession& session, WorldPacket& recv_data)
  144: {
  145:     ObjectGuid guid;
  146:     uint32 quest;
  147:     uint32 unk1;
  148:     recv_data >> guid >> quest >> unk1;
  149: 
  150:     if (!CanInteractWithQuestGiver(session, guid, "CMSG_QUESTGIVER_ACCEPT_QUEST"))
  151:     {
  152:         return;
  153:     }
  154: 
  155:     DEBUG_LOG("WORLD: Received opcode CMSG_QUESTGIVER_ACCEPT_QUEST - for %s to %s, quest = %u, unk1 = %u", session.GetPlayer()->GetGuidStr().c_str(), guid.GetString().c_str(), quest, unk1);
  156: 
  157:     Object* pObject = session.GetPlayer()->GetObjectByTypeMask(guid, TYPEMASK_CREATURE_GAMEOBJECT_PLAYER_OR_ITEM);
  158: 
  159:     // no or incorrect quest giver (player himself is questgiver for SPELL_EFFECT_QUEST_OFFER)
  160:     if (!pObject
  161:             || (pObject->GetTypeId() != TYPEID_PLAYER && !pObject->HasQuest(quest))
  162:             || (pObject->GetTypeId() == TYPEID_PLAYER && pObject != session.GetPlayer() && !((Player*)pObject)->CanShareQuest(quest))
  163:        )
  164:     {
  165:         session.GetPlayer()->PlayerTalkClass->CloseGossip();
  166:         session.GetPlayer()->ClearDividerGuid();
  167:         return;
  168:     }
  169: 
  170:     Quest const* qInfo = sObjectMgr.GetQuestTemplate(quest);
  171:     if (qInfo)
  172:     {
  173:         // prevent cheating
  174:         if (!session.GetPlayer()->CanTakeQuest(qInfo, true))
  175:         {
  176:             session.GetPlayer()->PlayerTalkClass->CloseGossip();
  177:             session.GetPlayer()->ClearDividerGuid();
  178:             return;
  179:         }
  180: 
  181:         if (Player* pPlayer = sPlayerRegistry.Find(session.GetPlayer()->GetDividerGuid()))
  182:         {
  183:             pPlayer->SendPushToPartyResponse(session.GetPlayer(), QUEST_PARTY_MSG_ACCEPT_QUEST);
  184:             session.GetPlayer()->ClearDividerGuid();
  185:         }
  186: 
  187:         if (session.GetPlayer()->CanAddQuest(qInfo, true))
  188:         {
  189:             session.GetPlayer()->AddQuest(qInfo, pObject);              // pObject (if it item) can be destroyed at call
  190: 
  191:             if (qInfo->HasQuestFlag(QUEST_FLAGS_PARTY_ACCEPT))
  192:             {
  193:                 if (Group* pGroup = session.GetPlayer()->GetGroup())
  194:                 {
  195:                     for (GroupReference* itr = pGroup->GetFirstMember(); itr != NULL; itr = itr->next())
  196:                     {
  197:                         Player* pPlayer = itr->getSource();
  198: 
  199:                         if (!pPlayer || pPlayer == session.GetPlayer()) // not self
  200:                         {
  201:                             continue;
  202:                         }
  203: 
  204:                         if (pPlayer->CanTakeQuest(qInfo, true))
  205:                         {
  206:                             pPlayer->SetDividerGuid(session.GetPlayer()->GetObjectGuid());
  207: 
  208:                             // need confirmation that any gossip window will close
  209:                             pPlayer->PlayerTalkClass->CloseGossip();
  210: 
  211:                             session.GetPlayer()->SendQuestConfirmAccept(qInfo, pPlayer);
  212:                         }
  213:                     }
  214:                 }
  215:             }
  216: 
  217:             if (session.GetPlayer()->CanCompleteQuest(quest))
  218:             {
  219:                 session.GetPlayer()->CompleteQuest(quest);
  220:             }
  221: 
  222:             session.GetPlayer()->GetAchievementMgr().StartTimedAchievementCriteria(ACHIEVEMENT_CRITERIA_TYPE_COMPLETE_QUEST, quest);
  223: 
  224:             session.GetPlayer()->PlayerTalkClass->CloseGossip();
  225: 
  226:             if (qInfo->GetSrcSpell() > 0)
  227:             {
  228:                 session.GetPlayer()->CastSpell(session.GetPlayer(), qInfo->GetSrcSpell(), true);
  229:             }
  230: 
  231:             return;
  232:         }
  233:     }
  234: 
  235:     session.GetPlayer()->PlayerTalkClass->CloseGossip();
  236: }
