  453: /**
  454:  * @brief Confirms acceptance of a quest shared by another party member.
  455:  *
  456:  * @param recv_data The received opcode packet.
  457:  */
  458: void QuestHandlers::HandleQuestConfirmAccept(WorldSession& session, WorldPacket& recv_data)
  459: {
  460:     uint32 quest;
  461:     recv_data >> quest;
  462: 
  463:     DEBUG_LOG("WORLD: Received opcode CMSG_QUEST_CONFIRM_ACCEPT quest = %u", quest);
  464: 
  465:     if (const Quest* pQuest = sObjectMgr.GetQuestTemplate(quest))
  466:     {
  467:         if (!pQuest->HasQuestFlag(QUEST_FLAGS_PARTY_ACCEPT))
  468:         {
  469:             return;
  470:         }
  471: 
  472:         Player* pOriginalPlayer = sPlayerRegistry.Find(session.GetPlayer()->GetDividerGuid());
  473: 
  474:         if (!pOriginalPlayer)
  475:         {
  476:             return;
  477:         }
  478: 
  479:         if (pQuest->IsAllowedInRaid())
  480:         {
  481:             if (!session.GetPlayer()->IsInSameRaidWith(pOriginalPlayer))
  482:             {
  483:                 return;
  484:             }
  485:         }
  486:         else
  487:         {
  488:             if (!session.GetPlayer()->IsInSameGroupWith(pOriginalPlayer))
  489:             {
  490:                 return;
  491:             }
  492:         }
  493: 
  494:         if (session.GetPlayer()->CanAddQuest(pQuest, true))
  495:         {
  496:             session.GetPlayer()->AddQuest(pQuest, NULL);                // NULL, this prevent DB script from duplicate running
  497:         }
  498: 
  499:         session.GetPlayer()->ClearDividerGuid();
  500:     }
  501: }
