  555: void QuestHandlers::HandlePushQuestToParty(WorldSession& session, WorldPacket& recvPacket)
  556: {
  557:     uint32 questId;
  558:     recvPacket >> questId;
  559: 
  560:     DEBUG_LOG("WORLD: Received opcode CMSG_PUSHQUESTTOPARTY quest = %u", questId);
  561: 
  562:     if (Quest const* pQuest = sObjectMgr.GetQuestTemplate(questId))
  563:     {
  564:         if (Group* pGroup = session.GetPlayer()->GetGroup())
  565:         {
  566:             for (GroupReference* itr = pGroup->GetFirstMember(); itr != NULL; itr = itr->next())
  567:             {
  568:                 Player* pPlayer = itr->getSource();
  569: 
  570:                 if (!pPlayer || pPlayer == session.GetPlayer())         // skip self
  571:                 {
  572:                     continue;
  573:                 }
  574: 
  575:                 session.GetPlayer()->SendPushToPartyResponse(pPlayer, QUEST_PARTY_MSG_SHARING_QUEST);
  576: 
  577:                 if (!pPlayer->SatisfyQuestStatus(pQuest, false))
  578:                 {
  579:                     session.GetPlayer()->SendPushToPartyResponse(pPlayer, QUEST_PARTY_MSG_HAVE_QUEST);
  580:                     continue;
  581:                 }
  582: 
  583:                 if (pPlayer->GetQuestStatusMgr().GetQuestStatus(questId) == QUEST_STATUS_COMPLETE)
  584:                 {
  585:                     session.GetPlayer()->SendPushToPartyResponse(pPlayer, QUEST_PARTY_MSG_FINISH_QUEST);
  586:                     continue;
  587:                 }
  588: 
  589:                 if (!pPlayer->CanTakeQuest(pQuest, false))
  590:                 {
  591:                     session.GetPlayer()->SendPushToPartyResponse(pPlayer, QUEST_PARTY_MSG_CANT_TAKE_QUEST);
  592:                     continue;
  593:                 }
  594: 
  595:                 if (!pPlayer->SatisfyQuestLog(false))
  596:                 {
  597:                     session.GetPlayer()->SendPushToPartyResponse(pPlayer, QUEST_PARTY_MSG_LOG_FULL);
  598:                     continue;
  599:                 }
  600: 
  601:                 if (pPlayer->GetDividerGuid())
  602:                 {
  603:                     session.GetPlayer()->SendPushToPartyResponse(pPlayer, QUEST_PARTY_MSG_BUSY);
  604:                     continue;
  605:                 }
  606: 
  607:                 pPlayer->PlayerTalkClass->SendQuestGiverQuestDetails(pQuest, session.GetPlayer()->GetObjectGuid(), true);
  608:                 pPlayer->SetDividerGuid(session.GetPlayer()->GetObjectGuid());
  609:             }
  610:         }
  611:     }
  612: }
